mapper.select:
SELECT DATE_FORMAT(A.EVENT_DT, '%Y-%m-%d %T' ) AS eventDt, B.DEVICE_NM AS deviceNm, A.DEVICE_IP AS deviceIp, A.MASTER_IP AS masterIp, A.DEVISION AS devision, A.EVENT_LEVEL AS eventLevel, A.TITLE AS title, A.CONTENT AS content FROM UI_SNMP_TRAP A LEFT JOIN UI_DEVICE B ON A.DEVICE_IP = B.DEVICE_IP WHERE 1=1
AND A.EVENT_DT BETWEEN STR_TO_DATE( CONCAT( #{startDt}, '000000' ), '%Y%m%d%H%i%s') AND STR_TO_DATE( CONCAT( #{endDt}, '235959' ), '%Y%m%d%H%i%s')
AND A.DEVICE_IP = #{deviceIp}
AND A.DEVISION = #{devision}
AND A.EVENT_LEVEL = #{eventLevel}
ORDER BY A.EVENT_DT DESC
LIMIT ${offset}, ${limit}
